CREATE VIEW [purchase].[GSTPurchaseRegister] AS SELECT i.PurchaseInvoiceId,i.InvoiceNumber,i.InvoiceDate,s.SupplierName,s.GSTIN,d.ProductId,p.HSNCode,d.GSTPercentage,SUM(d.Quantity*d.PurchasePrice-d.DiscountAmount)TaxableAmount,SUM(d.GSTAmount)GSTAmount FROM purchase.PurchaseInvoices i JOIN purchase.Suppliers s ON s.SupplierId=i.SupplierId JOIN purchase.PurchaseInvoiceItems d ON d.PurchaseInvoiceId=i.PurchaseInvoiceId JOIN master.Products p ON p.ProductId=d.ProductId WHERE i.IsDeleted=0 AND i.Status<>'DRAFT' GROUP BY i.PurchaseInvoiceId,i.InvoiceNumber,i.InvoiceDate,s.SupplierName,s.GSTIN,d.ProductId,p.HSNCode,d.GSTPercentage;
